CREATE OR REPLACE PROCEDURE VVRE_TROCA_STATUS_PROJ_COMP (
    P_NR_SEQ_PROJETO IN VVRE_PROJ_COMPRAS.NR_SEQUENCIA%TYPE)
IS
    V_NR_SEQUENCIA VVRE_HIST_PROJ.NR_SEQUENCIA%TYPE;
BEGIN

    -- Insere o registro
    UPDATE VVRE_PROJ_COMPRAS SET IE_STATUS = 'EX', DT_ATUALIZACAO = sysdate,
    NM_USUARIO = obter_usuario_ativo
    where NR_SEQUENCIA = P_NR_SEQ_PROJETO

    -- Gerar históricos
    VVRE_GERAR_HIST_PROJ_COMP(P_NR_SEQ_PROJETO,'Troca de status realizada. /n Status Aprovado, Usuario: '|| obter_usuario_ativo);

    COMMIT;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END VVRE_TROCA_STATUS_PROJ_COMP;
/

